discrete PowerManagementSystem
port:
    event input real VehicleConnected;
    event input real ChargingRequest;
    event input real SafetyCheckPassed;
    event input real GridPowerAvailable;
    event input real BatteryFull;
    event input real UserStop;
    event output real StartCharging;
    event output real StopCharging;
state:
    initial state Startup
        when entry() then
            statehold(0);
        end;
        when receive(VehicleConnected) then
            transition(DetectVehicle);
        end;
        when receive(ChargingRequest) then
            transition(DetectVehicle);
        end;
    end;

    state DetectVehicle
        when entry() then
            statehold(0);
        end;
        when receive(SafetyCheckPassed) then
            transition(StartCharging);
            out
                send(StartCharging, 1);
        end;
        when receive(GridPowerAvailable) then
            transition(StartCharging);
            out
                send(StartCharging, 1);
        end;
    end;

    state StartCharging
        when entry() then
            statehold(0);
        end;
        when receive(BatteryFull) then
            transition(StopCharging);
            out
                send(StopCharging, 1);
        end;
        when receive(UserStop) then
            transition(StopCharging);
            out
                send(StopCharging, 1);
        end;
    end;

    state StopCharging
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(Startup);
        end;
    end;
end;
end;

discrete ChargerControlSystem
port:
    event input real ValidConnection;
    event input real StartCharging;
    event input real FaultDetected;
    event input real FaultResolved;
    event output real BeginCharging;
    event output real AbortCharging;
state:
    initial state Idle
        when entry() then
            statehold(0);
        end;
        when receive(ValidConnection) then
            transition(Connected);
        end;
    end;

    state Connected
        when entry() then
            statehold(0);
        end;
        when receive(StartCharging) then
            transition(Charging);
            out
                send(BeginCharging, 1);
        end;
    end;

    state Charging
        when entry() then
            statehold(0);
        end;
        when receive(FaultDetected) then
            transition(Fault);
            out
                send(AbortCharging, 1);
        end;
    end;

    state Fault
        when entry() then
            statehold(0);
        end;
        when receive(FaultResolved) then
            transition(Idle);
        end;
    end;
end;
end;

discrete UserInteractionSystem
port:
    event input real StartButtonPressed;
    event input real PaymentMethodValidated;
    event input real UserConfirmed;
    event input real ChargingComplete;
    event output real ShowWelcomeScreen;
    event output real ShowPaymentSelection;
    event output real ShowConfirmationScreen;
    event output real ShowChargingInProgress;
state:
    initial state WelcomeScreen
        when entry() then
            statehold(0);
        end;
        when receive(StartButtonPressed) then
            transition(PaymentSelection);
            out
                send(ShowPaymentSelection, 1);
        end;
    end;

    state PaymentSelection
        when entry() then
            statehold(0);
        end;
        when receive(PaymentMethodValidated) then
            transition(ConfirmationScreen);
            out
                send(ShowConfirmationScreen, 1);
        end;
    end;

    state ConfirmationScreen
        when entry() then
            statehold(0);
        end;
        when receive(UserConfirmed) then
            transition(ChargingInProgress);
            out
                send(ShowChargingInProgress, 1);
        end;
    end;

    state ChargingInProgress
        when entry() then
            statehold(0);
        end;
        when receive(ChargingComplete) then
            transition(WelcomeScreen);
            out
                send(ShowWelcomeScreen, 1);
        end;
    end;
end;
end;

discrete SafetyMonitoringSystem
port:
    event input real ThresholdExceeded;
    event input real FaultResolved;
    event output real TriggerWarning;
    event output real InitiateEmergencyShutdown;
state:
    initial state NormalOperation
        when entry() then
            statehold(0);
        end;
        when receive(ThresholdExceeded) then
            transition(Warning);
            out
                send(TriggerWarning, 1);
        end;
    end;

    state Warning
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(EmergencyShutdown);
            out
                send(InitiateEmergencyShutdown, 1);
        end;
    end;

    state EmergencyShutdown
        when entry() then
            statehold(0);
        end;
        when receive(FaultResolved) then
            transition(NormalOperation);
        end;
    end;
end;
end;

